  -- Reabre jan–set caso algum tenha ficado fechado em teste.
  delete from public.meses_fechados where lar_id = v_lar and competencia between '2026-01-01' and '2026-09-01';

  -- Conta técnica do histórico: desativada e com saldo inicial em 30/09 (não afeta saldos).
  insert into public.contas (lar_id, nome, natureza, tipo, saldo_inicial, data_saldo_inicial, ativa, ordem)
  values (v_lar, 'Histórico da planilha', 'PF', 'dinheiro', 0, '2026-09-30', false, 999)
  returning id into v_conta;

  for m in select * from jsonb_array_elements(v_dados) loop
    v_mes := make_date(2026, (m->>'mes')::int, 1);
    v_data := make_date(2026, (m->>'mes')::int, (m->>'ultimo')::int);

    -- Renda da empresa (por cliente)
    for x in select * from jsonb_array_elements(m->'clientes') loop
      v_nome := coalesce(v_depara->>(x->>'nome'), x->>'nome');
      select id into v_cli from public.clientes where lar_id = v_lar and lower(trim(nome)) = lower(trim(v_nome)) limit 1;
      if v_cli is null then
        insert into public.clientes (lar_id, nome) values (v_lar, v_nome) returning id into v_cli;
      end if;
      select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'entrada' and lower(trim(nome)) = 'renda da empresa' limit 1;
      if v_cat is null then
        select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'renda_empresa' order by ordem limit 1;
      end if;
      insert into public.entradas (lar_id, data, competencia, valor, descricao, categoria_id, cliente_id, conta_id)
      values (v_lar, v_data, v_mes, (x->>'valor')::numeric, 'Importado da planilha', v_cat, v_cli, v_conta);
    end loop;

    -- Outras rendas (fora do dízimo)
    for x in select * from jsonb_array_elements(m->'outras') loop
      select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'entrada'
        and lower(trim(nome)) = case when lower(x->>'nome') like 'aluguel%' then 'aluguel recebido' else 'outras rendas' end limit 1;
      if v_cat is null then
        select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'outras_rendas' order by ordem limit 1;
      end if;
      insert into public.entradas (lar_id, data, competencia, valor, descricao, categoria_id, conta_id)
      values (v_lar, v_data, v_mes, (x->>'valor')::numeric, x->>'nome', v_cat, v_conta);
    end loop;

    -- Contas do mês (pagas)
    for x in select * from jsonb_array_elements(m->'saidas') loop
      select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'saida' and lower(trim(nome)) = lower(trim(x->>'cat')) limit 1;
      if v_cat is null then
        select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'saida' and lower(trim(nome)) = 'outras despesas' limit 1;
      end if;
      if v_cat is null then
        select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'despesa_casa' order by ordem limit 1;
      end if;
      insert into public.despesas (lar_id, descricao, categoria_id, competencia, vencimento, valor, origem)
      values (v_lar, x->>'nome', v_cat, v_mes, make_date(2026, (m->>'mes')::int, (x->>'dia')::int), (x->>'valor')::numeric, 'conta')
      returning id into v_desp;
      insert into public.pagamentos (lar_id, despesa_id, data, valor, conta_id)
      values (v_lar, v_desp, make_date(2026, (m->>'mes')::int, (x->>'dia')::int), (x->>'valor')::numeric, v_conta);
    end loop;

    -- Pix e dinheiro do dia a dia
    select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'saida' and lower(trim(nome)) = 'pix e dinheiro do dia a dia' limit 1;
    if v_cat is null then
      select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'despesa_casa' order by ordem limit 1;
    end if;
    for x in select * from jsonb_array_elements(m->'pix') loop
      insert into public.despesas (lar_id, descricao, categoria_id, competencia, vencimento, valor, origem)
      values (v_lar, x->>'nome', v_cat, v_mes, v_data, (x->>'valor')::numeric, 'avulsa')
      returning id into v_desp;
      insert into public.pagamentos (lar_id, despesa_id, data, valor, conta_id)
      values (v_lar, v_desp, v_data, (x->>'valor')::numeric, v_conta);
    end loop;

    -- Dízimo: o app calcula; o valor da planilha entra como pago.
    perform public._sync_dizimo(v_lar, v_mes);
    if (m->>'dizimo')::numeric > 0 then
      select id into v_diz from public.despesas where lar_id = v_lar and origem = 'dizimo' and competencia = v_mes limit 1;
      if v_diz is null then
        select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'dizimo' order by (lower(nome) like 'd%zimo%') desc, ordem limit 1;
        insert into public.despesas (lar_id, descricao, categoria_id, competencia, vencimento, valor, origem)
        values (v_lar, 'Dízimo', v_cat, v_mes, v_data, (m->>'dizimo')::numeric, 'dizimo')
        returning id into v_diz;
      end if;
      insert into public.pagamentos (lar_id, despesa_id, data, valor, conta_id)
      values (v_lar, v_diz, v_data, (m->>'dizimo')::numeric, v_conta);
      perform public._sync_dizimo(v_lar, v_mes);
    end if;

    -- Fecha o mês importado (pode reabrir em Conferência e fechamento).
    insert into public.meses_fechados (lar_id, competencia) values (v_lar, v_mes) on conflict do nothing;
  end loop;

  raise notice 'Importação concluída.';
end
$imp$;


